package com.gymflow.inventory;import com.gymflow.gym.Gym;import com.gymflow.product.Product;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="stock_movements",indexes=@Index(name="idx_stock_movement_gym_created",columnList="gym_id,created_at"))public class StockMovement{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="gym_id",nullable=false)private Gym gym;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="product_id",nullable=false)private Product product;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private MovementType type;@Column(nullable=false)private int quantity;@Column(length=250)private String reason;@Column(nullable=false,updatable=false)private Instant createdAt=Instant.now();protected StockMovement(){}public StockMovement(Gym gym,Product product,MovementType type,int quantity,String reason){this.gym=gym;this.product=product;this.type=type;this.quantity=quantity;this.reason=reason;}public UUID getId(){return id;}public UUID getGymId(){return gym.getId();}public UUID getProductId(){return product.getId();}public String getProductName(){return product.getName();}public MovementType getType(){return type;}public int getQuantity(){return quantity;}public String getReason(){return reason;}public Instant getCreatedAt(){return createdAt;}}
